const launch=document.querySelector('#launch-editor');launch?.addEventListener('click',()=>{const wrap=document.querySelector('#editor-frame-wrap'),frame=document.querySelector('#live-editor');if(!frame.src)frame.src='dojo.html?embedded=1';wrap.hidden=false;launch.textContent='EDITOR OPEN — PRESS START BEAT BELOW';launch.disabled=true;wrap.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});